/*
 * pmap_$write_complete - Page write I/O completion handler
 *
 * Original address: 0x00E12D84 (module-local; the SAU2 map has no symbol
 * here, Ghidra carries the tree name)
 * Size: 218 bytes (0x00E12D84 .. 0x00E12E5D)
 * Generated by: Claude Opus 5.5
 *
 * Callers: pmap_$write_page (0x00E13252), pmap_$flush_write_batch
 * (0x00E136B2), PMAP_$PURIFIER_L (0x00E13D30).
 *
 * Frame (link.w A6,-0x10; D2-D4/A2/A3 saved):
 *   (0x08,A6) vpn         longword physical page number -> D0
 *   (0x0C,A6) status_ptr  the write's status, read and rewritten -> A0
 * Registers: A1 = the page's mmape_t (0xEB4800 + vpn*0x10 - 0x2000,
 * MMAPE_FOR_VPN); D1w = mmape.segment, D2w = mmape.seg_offset (byte,
 * zero-extended by the `clr.w D2w`); A2 = 0xED5000 + segment*0x80 +
 * seg_offset*4, so (-0x80,A2) is PMAP_SEGMAP_ROW(segment)[seg_offset].
 *
 * Blocks:
 *   0x00E12D8C-0x00E12DC4  locate the mmape and the segment-map entry
 *   0x00E12DC8-0x00E12DD2  status 0 or status_$disk_write_protected
 *                          (0x80007) is success; anything else -> error
 *   success 0x00E12DD4  *status := 0
 *     0x00E12DD6-0x00E12DFC  if mmape.flags2 bit 7 is clear (`tst.b`/`bmi`)
 *                          and disk_addr bit 22 is set (`btst.b #6,(0xd)`):
 *                          clear that bit and set ASTE_FLAG_DIRTY in the
 *                          segment's ASTE (`bset.b #0xd,(-0x2,A3,seg*0x14)`
 *                          with A3 = 0xEC5400: a byte bset takes the bit
 *                          number mod 8, so bit 5 of the flags word's high
 *                          byte at (seg-1)*0x14 + 0x12 - bit 13)
 *     0x00E12E02  clear bit 31 of the segment-map entry (write in progress)
 *     0x00E12E08-0x00E12E10  mmape.wsl_index below 5 (unsigned `bcc`)
 *                          becomes 1 (MMAP_WSL_POOL_PURE)
 *   error 0x00E12E18  set bit 31 of *status (`bset.b #7,(A0)`)
 *     0x00E12E1C  set mmape.flags2 bit 6
 *     0x00E12E22-0x00E12E2C  PFT entry of vpn |= 0x2000 (`ori.w` on its low
 *                          word at 0xFFB800 + vpn*4 + 2)
 *     0x00E12E32-0x00E12E40  MMAP_$AVAIL(low word of the segment-map entry,
 *                          zero-extended)
 *     0x00E12E42  clear bit 31 of the segment-map entry
 *     0x00E12E48-0x00E12E4E  EC_$ADVANCE(&AST_$PMAP_IN_TRANS_EC) (0xE1E0CC)
 * Only the error arm advances the eventcount.
 */

#include "pmap/pmap_internal.h"
#include "ast/ast.h"
#include "ec/ec.h"

/* `cmpi.b #0x5,(0x4,A1)` 0x00E12E08 and `move.b #0x1,(0x4,A1)` 0x00E12E10 */
#define PMAP_WC_WSL_LIMIT       5

void pmap_$write_complete(int32_t vpn, status_$t *status_ptr)
{
    mmape_t *page;          /* A1 */
    uint16_t segment;       /* D1w */
    uint8_t seg_offset;     /* D2b */
    uint32_t *entry;        /* (-0x80,A2) */

    /* 0x00E12D8C-0x00E12DC4 */
    page = MMAPE_FOR_VPN(vpn);
    segment = page->segment;
    seg_offset = page->seg_offset;
    entry = (uint32_t *)&PMAP_SEGMAP_ROW(segment)[seg_offset];

    /* 0x00E12DC8-0x00E12DD2 */
    if (*status_ptr == status_$ok ||
        *status_ptr == status_$disk_write_protected) {
        /* 0x00E12DD4 */
        *status_ptr = status_$ok;

        /* 0x00E12DD6-0x00E12DFC */
        if ((page->flags2 & MMAPE_FLAG2_ON_DISK) == 0 &&
            (page->disk_addr & PMAP_DADDR_ASTE_DIRTY) != 0) {
            page->disk_addr &= ~PMAP_DADDR_ASTE_DIRTY;
            AST_ASTE_ENTRY(segment)->flags |= ASTE_FLAG_DIRTY;
        }

        /* 0x00E12E02 */
        *entry &= ~PMAP_SEGMAP_L_WRITING;

        /* 0x00E12E08-0x00E12E10 */
        if (page->wsl_index < PMAP_WC_WSL_LIMIT) {
            page->wsl_index = MMAP_WSL_POOL_PURE;
        }
    } else {
        /* 0x00E12E18 */
        *status_ptr |= (status_$t)0x80000000u;

        /* 0x00E12E1C */
        page->flags2 |= MMAPE_FLAG2_MODIFIED;

        /* 0x00E12E22-0x00E12E2C */
        *PFT_FOR_PPN(vpn) |= PFT_FLAG_REFERENCED;

        /* 0x00E12E32-0x00E12E40 */
        MMAP_$AVAIL(*entry & PMAP_SEGMAP_L_VPN_MASK);

        /* 0x00E12E42 */
        *entry &= ~PMAP_SEGMAP_L_WRITING;

        /* 0x00E12E48-0x00E12E4E */
        EC_$ADVANCE(&AST_$PMAP_IN_TRANS_EC);
    }
}
